import React, { useEffect, useState } from "react";
import axios from "axios";
import { useNavigate, useSearchParams } from 'react-router-dom';
import { MapContainer, TileLayer, CircleMarker, Popup, useMap } from 'react-leaflet';
import 'leaflet/dist/leaflet.css';
import "./RiverDashboard.css";
import L from 'leaflet';

const API_BASE_URL = process.env.NODE_ENV === 'production'
  ? 'https://aiiot-1.onrender.com'
  : 'http://localhost:8000';

const ITEMS_PER_PAGE = 10;

// ---------------------------------------------------------
// 🎨 HELPER: Risk Color Logic
// ---------------------------------------------------------
const getRiskStatus = (depth, isNormalState) => {
  // If the overall river state is Normal, force everything to look Safe
  if (isNormalState) {
    return {
      color: "#10b981", // Green
      bg: "rgba(16, 185, 129, 0.1)",
      label: "Safe / Normal Flow",
      icon: "fa-check-circle"
    };
  }

  // Otherwise, use the standard flood thresholds
  if (depth <= 3) return { color: "#10b981", bg: "rgba(16, 185, 129, 0.1)", label: "Low Risk", icon: "fa-check-circle" };
  if (depth < 8) return { color: "#f59e0b", bg: "rgba(245, 158, 11, 0.1)", label: "Moderate Risk", icon: "fa-exclamation-circle" };
  return { color: "#ef4444", bg: "rgba(239, 68, 68, 0.1)", label: "Critical Risk", icon: "fa-exclamation-triangle" };
};

const generateSmartName = (osmData) => {
  if (!osmData) return "Unknown Location";
  const addr = osmData.address || {};
  const street = addr.road || addr.street || addr.pedestrian || addr.path || addr.lane;
  const area = addr.neighbourhood || addr.suburb || addr.residential || addr.village;
  const town = addr.town || addr.city || addr.county;

  if (street && area) return `${street}, ${area}`;
  if (street && town) return `${street}, ${town}`;
  if (area && town) return `${area}, ${town}`;
  if (osmData.display_name) return osmData.display_name.split(", ").slice(0, 2).join(", ");
  return town || "Flood Point";
};

// ---------------------------------------------------------
// 📍 COMPONENT 1: Map Popup
// ---------------------------------------------------------
const LocationPopup = ({ lat, lon, depth, explanation, isNormalState }) => {
  const [address, setAddress] = useState("Loading details...");
  const [title, setTitle] = useState("Location Details");
  const status = getRiskStatus(depth, isNormalState);

  useEffect(() => {
    const fetchAddress = async () => {
      try {
        const url = `https://nominatim.openstreetmap.org/reverse?format=json&lat=${lat}&lon=${lon}`;
        const res = await axios.get(url);
        if (res.data) {
          setTitle(generateSmartName(res.data));
          setAddress(res.data.display_name);
        }
      } catch (err) { setAddress("Address unavailable"); }
    };
    fetchAddress();
  }, [lat, lon]);

  return (
    <div style={{ fontFamily: 'Inter, sans-serif', minWidth: '200px' }}>
      <strong style={{ fontSize: '14px', color: '#1e3a8a', display: 'block', marginBottom: '4px' }}>{title}</strong>
      <div style={{ height: '1px', background: '#e2e8f0', margin: '4px 0' }}></div>
      {/* Only show depth if NOT in normal state, to avoid confusing users with '10m' depth when river is low */}
      {!isNormalState && (
        <div style={{ fontSize: '12px', margin: '4px 0' }}>
          <span style={{ color: '#64748b' }}>Est. Inundation:</span>
          <strong style={{ color: status.color, marginLeft: '5px' }}>{depth}m</strong>
        </div>
      )}
      <div style={{ fontSize: '12px', margin: '4px 0' }}><span style={{ color: '#64748b' }}>Condition:</span> <span style={{ color: status.color, fontWeight: '600' }}>{status.label}</span></div>
      <div style={{ fontSize: '11px', marginTop: '8px', color: '#94a3b8', lineHeight: '1.2', borderTop: '1px dashed #e2e8f0', paddingTop: '4px' }}>{address}</div>
    </div>
  );
};

// ---------------------------------------------------------
// 🗺️ COMPONENT 2: Map Controls (Search & Location)
// ---------------------------------------------------------
const MapController = ({ targetLoc }) => {
  const map = useMap();
  useEffect(() => {
    if (targetLoc) {
      map.flyTo(targetLoc, 14, { animate: true, duration: 1.5 });
    }
  }, [targetLoc, map]);
  return null;
};

const CustomMapControls = ({ onSearch, onFindMe }) => {
  const [query, setQuery] = useState("");
  const [searching, setSearching] = useState(false);

  const handleSearch = async (e) => {
    e.preventDefault();
    if (!query.trim()) return;
    setSearching(true);
    try {
      const res = await axios.get(`https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(query)}&limit=1`);
      if (res.data && res.data.length > 0) {
        const { lat, lon } = res.data[0];
        onSearch([parseFloat(lat), parseFloat(lon)]);
      }
    } catch (err) { console.error("Search error:", err); }
    finally { setSearching(false); }
  };

  return (
    <div className="map-controls-suite" style={{
      position: 'absolute', top: '24px', left: '24px', zIndex: 1000,
      display: 'flex', flexDirection: 'column', gap: '16px', width: '380px'
    }}>
      {/* Search Bar - Modern Glassmorphism */}
      <form onSubmit={handleSearch} style={{
        display: 'flex',
        background: 'rgba(255, 255, 255, 0.8)',
        backdropFilter: 'blur(12px)',
        WebkitBackdropFilter: 'blur(12px)',
        boxShadow: '0 8px 32px rgba(0, 0, 0, 0.1)',
        borderRadius: '16px',
        overflow: 'hidden',
        border: '1px solid rgba(255, 255, 255, 0.3)',
        padding: '4px'
      }}>
        <div style={{ padding: '12px 16px', color: '#1e40af' }}>
          <i className="fas fa-search"></i>
        </div>
        <input
          type="text" value={query} onChange={(e) => setQuery(e.target.value)}
          placeholder="Search location (e.g. Aluva)..."
          style={{
            flex: 1, padding: '12px 0', border: 'none', outline: 'none',
            fontSize: '1rem', background: 'transparent', color: '#1e293b',
            fontWeight: '500'
          }}
        />
        <button type="submit" style={{
          background: '#1e40af', color: 'white', border: 'none', padding: '0 24px',
          borderRadius: '12px', cursor: 'pointer', transition: 'all 0.3s cubic-bezier(0.4, 0, 0.2, 1)',
          fontWeight: '600'
        }} onMouseOver={(e) => e.target.style.background = '#1e3a8a'} onMouseOut={(e) => e.target.style.background = '#1e40af'}>
          {searching ? <i className="fas fa-circle-notch fa-spin"></i> : "Find"}
        </button>
      </form>

      {/* Quick Actions Bar */}
      <div style={{ display: 'flex', gap: '8px' }}>
        <button onClick={onFindMe} style={{
          background: 'rgba(255, 255, 255, 0.8)',
          backdropFilter: 'blur(12px)',
          WebkitBackdropFilter: 'blur(12px)',
          color: '#1e40af',
          border: '1px solid rgba(255, 255, 255, 0.3)',
          padding: '12px 20px', borderRadius: '14px', cursor: 'pointer',
          boxShadow: '0 4px 12px rgba(0, 0, 0, 0.08)',
          fontWeight: '700', fontSize: '0.9rem',
          display: 'flex', alignItems: 'center', gap: '10px', transition: 'all 0.3s ease'
        }} onMouseOver={(e) => { e.currentTarget.style.transform = 'translateY(-2px)'; e.currentTarget.style.background = 'white'; }} onMouseOut={(e) => { e.currentTarget.style.transform = 'translateY(0)'; e.currentTarget.style.background = 'rgba(255, 255, 255, 0.8)'; }}>
          <i className="fas fa-location-arrow"></i> Find Me
        </button>

        <div style={{
          background: 'rgba(255, 255, 255, 0.8)',
          backdropFilter: 'blur(12px)',
          color: '#64748b',
          border: '1px solid rgba(255, 255, 255, 0.3)',
          padding: '12px 20px', borderRadius: '14px',
          boxShadow: '0 4px 12px rgba(0,0,0,0.08)',
          fontSize: '0.9rem', fontWeight: '600',
          display: 'flex', alignItems: 'center', gap: '8px'
        }}>
          <i className="fas fa-map"></i> Standard View
        </div>
      </div>
    </div>
  );
};

const MapLegend = () => (
  <div style={{
    position: 'absolute', bottom: '20px', right: '20px', zIndex: 1000,
    background: 'rgba(255, 255, 255, 0.9)', backdropFilter: 'blur(5px)',
    padding: '15px', borderRadius: '12px', boxShadow: '0 4px 15px rgba(0,0,0,0.1)',
    border: '1px solid rgba(255,255,255,0.2)', fontSize: '0.8rem'
  }}>
    <h5 style={{ margin: '0 0 10px 0', fontSize: '0.85rem', color: '#1e3a8a', fontWeight: '700' }}>Risk Legend</h5>
    <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
        <span style={{ width: '12px', height: '12px', borderRadius: '50%', background: '#ef4444' }}></span>
        <span>Critical Risk (&gt;8m)</span>
      </div>
      <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
        <span style={{ width: '12px', height: '12px', borderRadius: '50%', background: '#f59e0b' }}></span>
        <span>Moderate Risk (3m-8m)</span>
      </div>
      <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
        <span style={{ width: '12px', height: '12px', borderRadius: '50%', background: '#10b981' }}></span>
        <span>Low Risk (&lt;3m)</span>
      </div>
    </div>
  </div>
);

// ---------------------------------------------------------
// 🔘 COMPONENT 3: Pagination Controls
// ---------------------------------------------------------
const Pagination = ({ currentPage, totalItems, onPageChange }) => {
  const totalPages = Math.ceil(totalItems / ITEMS_PER_PAGE);
  if (totalPages <= 1) return null;

  return (
    <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', gap: '15px', padding: '25px 0' }}>
      <button
        onClick={() => onPageChange(currentPage - 1)} disabled={currentPage === 1}
        style={{
          padding: '8px 16px', borderRadius: '6px', border: '1px solid #e2e8f0',
          background: currentPage === 1 ? '#f8fafc' : '#ffffff',
          color: currentPage === 1 ? '#cbd5e1' : '#1e40af',
          cursor: currentPage === 1 ? 'not-allowed' : 'pointer',
          fontWeight: '500', transition: 'all 0.2s'
        }}
      >
        <i className="fas fa-chevron-left"></i> Prev
      </button>

      <span style={{ fontSize: '0.9rem', color: '#64748b', fontWeight: '500' }}>
        Page <strong>{currentPage}</strong> of {totalPages}
      </span>

      <button
        onClick={() => onPageChange(currentPage + 1)} disabled={currentPage === totalPages}
        style={{
          padding: '8px 16px', borderRadius: '6px', border: '1px solid #e2e8f0',
          background: currentPage === totalPages ? '#f8fafc' : '#ffffff',
          color: currentPage === totalPages ? '#cbd5e1' : '#1e40af',
          cursor: currentPage === totalPages ? 'not-allowed' : 'pointer',
          fontWeight: '500', transition: 'all 0.2s'
        }}
      >
        Next <i className="fas fa-chevron-right"></i>
      </button>
    </div>
  );
};

// ---------------------------------------------------------
// 📋 COMPONENT 3: List Item
// ---------------------------------------------------------
const AffectedAreaItem = ({ data, index }) => {
  const [expanded, setExpanded] = useState(false);
  const [details, setDetails] = useState(null);
  const [loading, setLoading] = useState(false);
  const [displayName, setDisplayName] = useState(data.place);

  const status = getRiskStatus(data.depth, false); // Always show real status in list if list is visible

  const fetchDetails = async () => {
    if (details || loading) return;
    setLoading(true);
    try {
      const url = `https://nominatim.openstreetmap.org/reverse?format=json&lat=${data.lat}&lon=${data.lon}`;
      const res = await axios.get(url);
      if (res.data) {
        setDetails(res.data);
        setDisplayName(generateSmartName(res.data));
      }
    } catch (e) { setDetails({ error: true }); }
    finally { setLoading(false); }
  };

  useEffect(() => {
    if (data.depth >= 8) {
      const timer = setTimeout(() => { fetchDetails(); }, index * 800);
      return () => clearTimeout(timer);
    }
  }, [data.depth, index]);

  return (
    <div style={{
      background: '#ffffff', borderRadius: '12px', marginBottom: '16px',
      border: '1px solid #e2e8f0', borderLeft: `6px solid ${status.color}`,
      padding: '24px', boxShadow: '0 4px 6px -1px rgba(0,0,0,0.05), 0 2px 4px -1px rgba(0,0,0,0.03)',
      transition: 'all 0.3s cubic-bezier(0.4, 0, 0.2, 1)',
      cursor: 'pointer'
    }} onMouseOver={(e) => { e.currentTarget.style.transform = 'translateX(8px)'; e.currentTarget.style.boxShadow = '0 10px 15px -3px rgba(0,0,0,0.1)'; }} onMouseOut={(e) => { e.currentTarget.style.transform = 'translateX(0)'; e.currentTarget.style.boxShadow = '0 4px 6px -1px rgba(0,0,0,0.05)'; }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '15px' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '20px' }}>
          <div style={{
            background: status.bg, color: status.color, width: '50px', height: '50px',
            borderRadius: '12px', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1.4rem',
            boxShadow: 'inset 0 0 0 1px rgba(0,0,0,0.05)'
          }}>
            <i className={`fas ${status.icon}`}></i>
          </div>
          <div>
            <h4 style={{ margin: '0 0 5px 0', fontSize: '1.1rem', color: '#1e293b', fontWeight: '700', display: 'flex', alignItems: 'center', gap: '10px' }}>
              {displayName}
              {loading && <i className="fas fa-circle-notch fa-spin" style={{ fontSize: '0.9rem', color: '#94a3b8' }}></i>}
            </h4>

            <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
              <span style={{ fontSize: '0.85rem', color: '#64748b', display: 'flex', alignItems: 'center', gap: '5px' }}>
                <i className="fas fa-water" style={{ fontSize: '0.8rem' }}></i> Inundation: <strong style={{ color: status.color }}>{data.depth}m</strong>
              </span>
              <span style={{ width: '4px', height: '4px', borderRadius: '50%', background: '#cbd5e1' }}></span>
              <span style={{ fontSize: '0.85rem', color: status.color, fontWeight: '600', textTransform: 'uppercase', letterSpacing: '0.5px' }}>
                {status.label}
              </span>
            </div>
          </div>
        </div>
        <button
          onClick={() => { if (!expanded && !details) fetchDetails(); setExpanded(!expanded); }}
          style={{
            padding: '10px 20px', background: expanded ? '#f1f5f9' : '#1e40af', color: expanded ? '#64748b' : '#ffffff',
            border: 'none',
            borderRadius: '8px', cursor: 'pointer', fontWeight: '600', fontSize: '0.85rem',
            display: 'flex', alignItems: 'center', gap: '8px', transition: 'all 0.2s',
            boxShadow: expanded ? 'none' : '0 4px 12px rgba(30, 64, 175, 0.2)'
          }}
        >
          {expanded ? <><i className="fas fa-times"></i> Close</> : <><i className="fas fa-map-marker-alt"></i> Locate</>}
        </button>
      </div>

      {expanded && (
        <div style={{ marginTop: '20px', paddingTop: '15px', borderTop: '1px solid #f1f5f9', fontSize: '0.9rem', background: '#f8fafc', padding: '15px', borderRadius: '6px' }}>
          {loading ? (
            <div style={{ color: '#64748b', display: 'flex', alignItems: 'center', gap: '10px' }}>
              <i className="fas fa-spinner fa-spin"></i> Retrieving geospatial data...
            </div>
          ) : details && !details.error ? (
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '20px' }}>
              <div style={{ gridColumn: 'span 2' }}>
                <small style={{ color: '#94a3b8', fontSize: '0.75rem', fontWeight: '600', letterSpacing: '0.5px' }}>OFFICIAL ADDRESS</small><br />
                <strong style={{ color: '#334155' }}>{details.display_name}</strong>
              </div>
              <div>
                <small style={{ color: '#94a3b8', fontSize: '0.75rem', fontWeight: '600', letterSpacing: '0.5px' }}>LOCALITY</small><br />
                <strong>{details.address.road || details.address.neighbourhood || details.display_name.split(',')[0]}</strong>
              </div>
              <div>
                <small style={{ color: '#94a3b8', fontSize: '0.75rem', fontWeight: '600', letterSpacing: '0.5px' }}>JURISDICTION</small><br />
                <strong>{details.address.village || details.address.town || "Angamali"}</strong>
              </div>
            </div>
          ) : (
            <div style={{ color: '#ef4444' }}>Location details temporarily unavailable.</div>
          )}
        </div>
      )}
    </div>
  );
};

// ---------------------------------------------------------
// 🚀 MAIN PAGE
// ---------------------------------------------------------
const FloodMap = () => {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const [loading, setLoading] = useState(true);
  const [floodData, setFloodData] = useState(null);

  const [severePage, setSeverePage] = useState(1);
  const [otherPage, setOtherPage] = useState(1);
  const [showAllAreas, setShowAllAreas] = useState(false);
  const [mapCenter, setMapCenter] = useState([10.16, 76.43]);
  const [searchPos, setSearchPos] = useState(null);
  const [userPos, setUserPos] = useState(null);

  const simulatedLevel = searchParams.get('level');

  useEffect(() => {
    const fetchFloodAnalysis = async () => {
      try {
        setLoading(true);
        const response = await axios.get(`${API_BASE_URL}/api/weather/flood-analysis`, {
          params: { level: simulatedLevel }
        });
        if (response.data) {
          if (response.data.data) response.data.data.sort((a, b) => b.depth - a.depth);
          setFloodData(response.data);
          setSeverePage(1);
          setOtherPage(1);
        }
      } catch (error) { console.error(error); }
      finally { setLoading(false); }
    };
    fetchFloodAnalysis();
  }, [simulatedLevel]);

  const handleLocateUser = () => {
    if ("geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition((pos) => {
        const coords = [pos.coords.latitude, pos.coords.longitude];
        setUserPos(coords);
        setMapCenter(coords);
      }, (err) => {
        alert("Permission to access location was denied or failed.");
      });
    } else {
      alert("Geolocation is not supported by your browser.");
    }
  };

  if (loading) return <div className="rd-loading"><div className="rd-spinner"></div><p>Calculating Flood Impact...</p></div>;

  const threshold = floodData?.current_water_level || 3.5;

  // ✅ SMART LOGIC: Is the situation actually dangerous?
  // If the water level is <= 3.0m, we consider it "Normal" and "Safe".
  // This prevents showing "Critical" red alerts when the river is actually safe.
  const isNormalState = threshold <= 3.0;

  // Filters
  const severeZones = floodData?.data?.filter(d => d.depth >= threshold) || [];
  const otherZones = floodData?.data?.filter(d => d.depth < threshold) || [];

  const currentSevere = severeZones.slice((severePage - 1) * ITEMS_PER_PAGE, severePage * ITEMS_PER_PAGE);
  const currentOther = otherZones.slice((otherPage - 1) * ITEMS_PER_PAGE, otherPage * ITEMS_PER_PAGE);

  return (
    <div className="flood-immersive-container" style={{
      height: '100vh',
      width: '100vw',
      overflow: 'hidden',
      position: 'relative',
      background: '#f1f5f9',
      fontFamily: 'Inter, sans-serif'
    }}>
      {/* 1. TOP OVERLAY HEADER */}
      <header style={{
        position: 'absolute', top: 0, left: 0, right: 0, zIndex: 1001,
        padding: '20px 30px', display: 'flex', justifyContent: 'space-between', alignItems: 'center',
        background: 'linear-gradient(to bottom, rgba(30, 64, 175, 0.8) 0%, rgba(30, 64, 175, 0) 100%)',
        color: 'white', pointerEvents: 'none'
      }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '15px', pointerEvents: 'auto' }}>
          <div style={{ fontSize: '1.8rem', fontWeight: '800', letterSpacing: '-0.5px' }}>
            Periyar<span style={{ fontWeight: '300', opacity: 0.8 }}>FloodMap</span>
          </div>
          <div style={{
            background: isNormalState ? 'rgba(16, 185, 129, 0.2)' : 'rgba(239, 68, 68, 0.2)',
            border: `1px solid ${isNormalState ? '#10b981' : '#ef4444'}`,
            color: isNormalState ? '#34d399' : '#f87171',
            padding: '4px 12px', borderRadius: '20px', fontSize: '0.75rem', fontWeight: '700',
            textTransform: 'uppercase', letterSpacing: '1px'
          }}>
            <i className={`fas ${isNormalState ? 'fa-check-circle' : 'fa-exclamation-triangle'}`} style={{ marginRight: '6px' }}></i>
            {isNormalState ? "All Safe" : "Active Risk"}
          </div>
        </div>
        <div style={{ pointerEvents: 'auto' }}>
          <button
            onClick={() => navigate('/river-dashboard')}
            style={{
              padding: '10px 20px', background: 'rgba(255,255,255,0.15)', border: '1px solid rgba(255,255,255,0.3)',
              borderRadius: '12px', color: 'white', cursor: 'pointer', fontWeight: '600', backdropFilter: 'blur(10px)',
              transition: 'all 0.3s'
            }}
            onMouseOver={(e) => e.target.style.background = 'rgba(255,255,255,0.25)'}
            onMouseOut={(e) => e.target.style.background = 'rgba(255,255,255,0.15)'}
          >
            <i className="fas fa-arrow-left"></i> Dashboard
          </button>
        </div>
      </header>

      {/* 2. MAIN MAP (FULL SCREEN) */}
      <div style={{ height: '100%', width: '100%', position: 'relative' }}>
        <CustomMapControls onSearch={(pos) => { setMapCenter(pos); setSearchPos(pos); }} onFindMe={handleLocateUser} />
        <MapLegend />

        {/* Floating Water Level Widget */}
        <div style={{
          position: 'absolute', bottom: '30px', left: '30px', zIndex: 1000,
          background: 'rgba(255, 255, 255, 0.85)', backdropFilter: 'blur(12px)',
          padding: '20px', borderRadius: '24px', boxShadow: '0 12px 40px rgba(0,0,0,0.15)',
          border: '1px solid rgba(255,255,255,0.3)', width: '220px'
        }}>
          <div style={{ fontSize: '0.7rem', fontWeight: '700', color: '#64748b', textTransform: 'uppercase', letterSpacing: '1px', marginBottom: '4px' }}>River Gauge Level</div>
          <div style={{ fontSize: '2.5rem', fontWeight: '800', color: '#1e3a8a', lineHeight: '1' }}>
            {floodData?.current_water_level}<span style={{ fontSize: '1rem', color: '#94a3b8', marginLeft: '4px' }}>m</span>
          </div>
          <div style={{ height: '4px', background: '#e2e8f0', borderRadius: '4px', margin: '12px 0', overflow: 'hidden' }}>
            <div style={{
              width: `${Math.min((floodData?.current_water_level / 12) * 100, 100)}%`,
              height: '100%', background: isNormalState ? '#10b981' : (threshold < 8 ? '#f59e0b' : '#ef4444'),
              transition: 'width 1.5s ease'
            }}></div>
          </div>
          <div style={{ fontSize: '0.85rem', color: '#334155', fontWeight: '600' }}>
            {isNormalState ? "Below Warning" : (threshold < 8 ? "Moderate Inundation" : "Critical Flooding")}
          </div>
        </div>

        <MapContainer center={[10.16, 76.43]} zoom={13} style={{ height: "100%", width: "100%" }} zoomControl={false}>
          <TileLayer url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" attribution='&copy; OpenStreetMap' />
          <MapController targetLoc={mapCenter} />

          {userPos && (
            <CircleMarker center={userPos} radius={10} pathOptions={{ color: '#1e40af', fillColor: '#3b82f6', fillOpacity: 0.6, weight: 2 }}>
              <Popup><div style={{ fontWeight: 600, color: '#1e40af' }}><i className="fas fa-user-circle"></i> Current Location</div></Popup>
            </CircleMarker>
          )}

          {searchPos && (
            <CircleMarker center={searchPos} radius={12} pathOptions={{ color: '#ef4444', fillColor: '#fee2e2', fillOpacity: 0.8, weight: 3, dashArray: '5, 5' }}>
              <Popup><div style={{ fontWeight: 600, color: '#b91c1c' }}><i className="fas fa-search-location"></i> Target Area</div></Popup>
            </CircleMarker>
          )}

          {floodData?.data?.map((point, idx) => {
            const status = getRiskStatus(point.depth, isNormalState);
            return (
              <CircleMarker
                key={idx} center={[point.lat, point.lon]} radius={7}
                pathOptions={{
                  color: 'white',
                  weight: 1,
                  fillColor: status.color,
                  fillOpacity: 0.8
                }}
                eventHandlers={{
                  mouseover: (e) => { e.target.setStyle({ radius: 10, weight: 2 }); },
                  mouseout: (e) => { e.target.setStyle({ radius: 7, weight: 1 }); }
                }}
              >
                <Popup><LocationPopup {...point} isNormalState={isNormalState} /></Popup>
              </CircleMarker>
            );
          })}
        </MapContainer>
      </div>

      {/* 3. FLOATING SIDEBAR (RIGHT) */}
      <aside style={{
        position: 'absolute', top: '24px', right: '24px', bottom: '24px', zIndex: 1000,
        width: '400px', background: 'rgba(255, 255, 255, 0.85)', backdropFilter: 'blur(16px)',
        WebkitBackdropFilter: 'blur(16px)', borderRadius: '24px', boxShadow: '-12px 0 40px rgba(0,0,0,0.12)',
        border: '1px solid rgba(255,255,255,0.4)', display: 'flex', flexDirection: 'column',
        overflow: 'hidden'
      }}>
        {/* Sidebar Header */}
        <div style={{ padding: '24px', borderBottom: '1px solid rgba(0,0,0,0.05)' }}>
          <h3 style={{ margin: 0, fontSize: '1.25rem', color: '#1e293b', fontWeight: '800' }}>Impact Zones</h3>
          <p style={{ margin: '4px 0 0 0', fontSize: '0.85rem', color: '#64748b' }}>
            {isNormalState ? "Region currently safe from river flooding." : `${severeZones.length} critical and ${otherZones.length} moderate zones.`}
          </p>
        </div>

        {/* Sidebar Content (Scrollable) */}
        <div style={{ flex: 1, overflowY: 'auto', padding: '16px' }}>
          {isNormalState ? (
            <div style={{ textAlign: 'center', padding: '40px 20px' }}>
              <div style={{
                width: '64px', height: '64px', background: '#ecfdf5', color: '#10b981',
                borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center',
                margin: '0 auto 16px auto', fontSize: '1.5rem'
              }}>
                <i className="fas fa-check-shield"></i>
              </div>
              <h4 style={{ color: '#065f46', marginBottom: '8px' }}>Normal Flow</h4>
              <p style={{ fontSize: '0.85rem', color: '#64748b', lineHeight: '1.6' }}>
                Water levels at Kalady Gauge are within operational limits. No active flooding in residential sectors.
              </p>
            </div>
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
              {severeZones.length > 0 && (
                <div style={{ marginBottom: '16px' }}>
                  <div style={{ fontSize: '0.7rem', fontWeight: '800', color: '#ef4444', textTransform: 'uppercase', marginBottom: '12px', paddingLeft: '8px' }}>Critical Response Areas</div>
                  {currentSevere.map((item, index) => (
                    <div key={index}
                      onClick={() => setMapCenter([item.lat, item.lon])}
                      style={{ cursor: 'pointer' }}>
                      <AffectedAreaItem data={item} index={index} />
                    </div>
                  ))}
                  <Pagination currentPage={severePage} totalItems={severeZones.length} onPageChange={setSeverePage} />
                </div>
              )}

              {otherZones.length > 0 && (
                <div>
                  <div style={{ fontSize: '0.7rem', fontWeight: '800', color: '#f59e0b', textTransform: 'uppercase', marginBottom: '12px', paddingLeft: '8px' }}>Moderate Caution Areas</div>
                  {currentOther.map((item, index) => (
                    <div key={index}
                      onClick={() => setMapCenter([item.lat, item.lon])}
                      style={{ cursor: 'pointer' }}>
                      <AffectedAreaItem data={item} />
                    </div>
                  ))}
                  <Pagination currentPage={otherPage} totalItems={otherZones.length} onPageChange={setOtherPage} />
                </div>
              )}
            </div>
          )}
        </div>

        {/* Sidebar Footer */}
        <div style={{ padding: '16px 24px', background: '#f8fafc', borderTop: '1px solid rgba(0,0,0,0.05)', fontSize: '0.75rem', color: '#94a3b8', display: 'flex', gap: '10px', alignItems: 'center' }}>
          <i className="fas fa-satellite"></i>
          Last update: {new Date().toLocaleTimeString()} • OSM Real-time Data
        </div>
      </aside>
    </div>
  );
};

export default FloodMap;
